function containsDuplicate(nums) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(n)) return true;
    seen.add(n);
  }
  return false;
}
console.log(containsDuplicate([1, 2, 3, 1]) + ',' + containsDuplicate([1, 2, 3]));

