function firstUnique(s) {
  const count = {};
  for (const ch of s) count[ch] = (count[ch] || 0) + 1;
  for (let i = 0; i < s.length; i++) {
    if (count[s[i]] === 1) return i;
  }
  return -1;
}
console.log(firstUnique('leetcode') + ',' + firstUnique('loveleetcode'));

